from collections import Counter, deque

def transform(g):
    h,w=len(g),len(g[0]); seen=set(); single=[]
    for r in range(h):
      for c in range(w):
        if (r,c) in seen: continue
        col=g[r][c]; q=[(r,c)]; seen.add((r,c)); comp=[]
        while q:
          y,x=q.pop(); comp.append((y,x))
          for dy,dx in ((-1,0),(1,0),(0,-1),(0,1)):
            yy,xx=y+dy,x+dx
            if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and g[yy][xx]==col:
              seen.add((yy,xx)); q.append((yy,xx))
        if len(comp)==1: single.append((r,c))
    out=[row[:] for row in g]
    for r,c in single:
      vals=[g[rr][cc] for dr,dc in ((0,-1),(0,1),(-1,0),(1,0)) if 0<=(rr:=r+dr)<h and 0<=(cc:=c+dc)<w]
      if vals:
        cnt=Counter(vals); m=max(cnt.values()); out[r][c]=next(v for v in vals if cnt[v]==m)
    return out
