def transform_rect(g, radius=4):
    h,w=len(g),len(g[0]);seen=set(); isolated=[]
    for r in range(h):
      for c in range(w):
        if (r,c) in seen: continue
        color=g[r][c]; stack=[(r,c)];seen.add((r,c)); comp=[]
        while stack:
          y,x=stack.pop();comp.append((y,x))
          for dy,dx in ((-1,0),(1,0),(0,-1),(0,1)):
            yy,xx=y+dy,x+dx
            if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and g[yy][xx]==color:
              seen.add((yy,xx));stack.append((yy,xx))
        if len(comp)==1: isolated.append((r,c))
    out=[row[:] for row in g]
    for r,c in isolated:
      coords=[(r+dr,c+dc) for dr,dc in ((0,-1),(0,1),(-1,0),(1,0)) if 0<=r+dr<h and 0<=c+dc<w]
      vals=[g[y][x] for y,x in coords]; cnt=Counter(vals); m=max(cnt.values())
      candidates=[v for v in cnt if cnt[v]==m]
      if len(candidates)>1:
        def score(v):
          best=0
          top0=max(0,r-radius); bot0=min(h-1,r+radius); left0=max(0,c-radius); right0=min(w-1,c+radius)
          for top in range(top0,r+1):
           for bot in range(r,bot0+1):
            for left in range(left0,c+1):
             for right in range(c,right0+1):
              if (bot-top+1)*(right-left+1)<=best: continue
              ok=True
              for yy in range(top,bot+1):
               for xx in range(left,right+1):
                if (yy,xx)!=(r,c) and g[yy][xx]!=v:
                 ok=False; break
               if not ok:break
              if ok:best=(bot-top+1)*(right-left+1)
          return best
        scores={v:score(v) for v in candidates}
        best=max(scores.values()); candidates=[v for v in candidates if scores[v]==best]
      # Keep deterministic tie fallback based on earliest orthogonal neighbor.
      out[r][c]=next(g[y][x] for y,x in coords if g[y][x] in candidates)
    return out
