def transform_bbox(g):
 h,w=len(g),len(g[0]); seen=set(); comps=[]
 for r in range(h):
  for c in range(w):
   if (r,c) in seen:continue
   color=g[r][c]; st=[(r,c)];seen.add((r,c)); cells=[]
   while st:
