    for dy,dx in ((-1,0),(1,0),(0,-1),(0,1)):
     yy,xx=y+dy,x+dx
     if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and g[yy][xx]==color:
      seen.add((yy,xx));st.append((yy,xx))
   comps.append((color,cells,(min(y for y,x in cells),max(y for y,x in cells),min(x for y,x in cells),max(x for y,x in cells))))
 freq=Counter(v for row in g for v in row); bg=freq.most_common(1)[0][0]
 out=[row[:] for row in g]
 for color,cells,bbox in comps:
  if len(cells)!=1 or color==bg:continue
  r,c=cells[0]
