  for other,ocells,(r0,r1,c0,c1) in comps:
   if other==bg or len(ocells)<2:continue
   if r0<=r<=r1 and c0<=c<=c1:
    dist=min(abs(r-y)+abs(c-x) for y,x in ocells)
    candidates.append((other,len(ocells),dist))
  if candidates:
